#include <bits/stdc++.h>
using namespace std;const long long P=999911659,M=999911658,Q[4]={2,3,4679,35617};long long f[40005],d[1005],c[105][105];long long pw(long long a,long long b,long long p){long long r=1;for(;b;b>>=1,a=a*a%p)if(b&1)r=r*a%p;return r;}long long C(long long n,long long m,long long p){if(m>n)return 0;return f[n]*pw(f[m]*f[n-m]%p,p-2,p)%p;}long long L(long long n,long long m,long long p){long long r=1;while(n||m){r=r*C(n%p,m%p,p)%p;n/=p;m/=p;}return r;}int main(int V,char**v){ios::sync_with_stdio(0);cin.tie(0);int R=V>1?stoi(v[1]):1000;unsigned long long e=V>2?stoull(v[2]):1;mt19937_64 g(e);while(R--){int n=g()%80+1,z=0;long long a=g()%1000000000+1,x=0,y=0;c[0][0]=1;for(int i=1;i<=n;i++){c[i][0]=1;for(int j=1;j<=i;j++)c[i][j]=(c[i-1][j-1]+c[i-1][j])%M;}for(int i=1;i<=n;i++)if(n%i==0)d[z++]=i,y=(y+c[n][i])%M;for(int k=0;k<4;k++){long long p=Q[k],s=0,m=M/p;f[0]=1;for(int i=1;i<p;i++)f[i]=f[i-1]*i%p;for(int i=0;i<z;i++)s=(s+L(n,d[i],p))%p;x=(x+s*m%M*pw(m%p,p-2,p))%M;}if(pw(a,x,P)!=pw(a,y,P))return cout<<"WA\n",1;}cout<<"OK\n";}
